import 'package:flutter/material.dart';
import 'package:firebase_core/firebase_core.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:cloud_firestore/cloud_firestore.dart';

// ====== PASTE YOUR FIREBASE VALUES HERE (Step 3 of the guide) ======
const fbOptions = FirebaseOptions(
  apiKey: 'PASTE_API_KEY',
    appId: 'PASTE_APP_ID',
      messagingSenderId: 'PASTE_SENDER_ID',
        projectId: 'PASTE_PROJECT_ID',
        );
        // ===================================================================

        const stages = [
          ['R&I', '1 to 3'], ['Stripping', '4 to 15'], ['Washing', '16 to 19'],
            ['Reclamation', '20 to 37'], ['Painting', '38 to 41'], ['Assy-I', '42 to 46'],
              ['Assy-II', '47 to 58'], ['Assy-III', '59 to 69'], ['Hull Static', '70 to 73'],
                ['Hull Final', '74 to 76'], ['Turret integration', '77 to 83'],
                  ['QA Trial', '84 to 86'], ['QA RFR', '87 to 95'], ['T&R Static', '96 to 108'],
                    ['T&R Dynamic', '109 to 123'], ['T&R Final', '124 to 137'],
                    ];

                    Future<void> main() async {
                      WidgetsFlutterBinding.ensureInitialized();
                        await Firebase.initializeApp(options: fbOptions);
                          runApp(const App());
                          }

                          String fmtDate(DateTime d) =>
                              '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
                              String today() => fmtDate(DateTime.now());
                              String show(String? d) => (d == null || d.isEmpty) ? '—' : d.split('-').reversed.join('-');
                              int daysBetween(String a, String b) =>
                                  DateTime.parse(b).difference(DateTime.parse(a)).inDays;

                                  Map<String, dynamic> sg(Map v, int i) {
                                    final st = (v['st'] ?? {}) as Map;
                                      return Map<String, dynamic>.from((st['$i'] ?? {}) as Map);
                                      }

                                      int secOf(Map v) => (v['sec'] ?? 1) as int;

                                      // role == 'admin' -> both sections; admin1 / admin2 -> one section only
                                      bool canEditSec(Map? u, int s) {
                                        if (u == null) return false;
                                          return u['role'] == 'admin' ||
                                                (s == 1 && u['admin1'] == true) ||
                                                      (s == 2 && u['admin2'] == true);
                                                      }

                                                      int current(Map v) {
                                                        for (var i = 0; i < 16; i++) {
                                                            final s = sg(v, i);
                                                                if (s['in'] != null && s['out'] == null) return i;
                                                                  }
                                                                    for (var i = 15; i >= 0; i--) {
                                                                        if (sg(v, i)['out'] != null) return i == 15 ? 16 : i + 1;
                                                                          }
                                                                            return 0;
                                                                            }

                                                                            String status(Map v) {
                                                                              final c = current(v);
                                                                                if (c == 16) return 'Completed';
                                                                                  return sg(v, c)['in'] != null ? stages[c][0] : 'Next: ${stages[c][0]}';
                                                                                  }

                                                                                  class App extends StatelessWidget {
                                                                                    const App({super.key});
                                                                                      @override
                                                                                        Widget build(BuildContext context) => MaterialApp(
                                                                                                title: 'Vehicle Tracker',
                                                                                                        theme: ThemeData(colorSchemeSeed: Colors.blue, useMaterial3: true),
                                                                                                                darkTheme: ThemeData(
                                                                                                                            colorSchemeSeed: Colors.blue, useMaterial3: true, brightness: Brightness.dark),
                                                                                                                                    home: StreamBuilder<User?>(
                                                                                                                                              stream: FirebaseAuth.instance.authStateChanges(),
                                                                                                                                                        builder: (c, s) {
                                                                                                                                                                    if (s.connectionState == ConnectionState.waiting) {
                                                                                                                                                                                  return const Scaffold(body: Center(child: CircularProgressIndicator()));
                                                                                                                                                                                              }
                                                                                                                                                                                                          return s.data == null ? const Login() : Home(user: s.data!);
                                                                                                                                                                                                                    },
                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                  class Login extends StatefulWidget {
                                                                                                                                                                                                                                    const Login({super.key});
                                                                                                                                                                                                                                      @override
                                                                                                                                                                                                                                        State<Login> createState() => _LoginState();
                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                        class _LoginState extends State<Login> {
                                                                                                                                                                                                                                          final e = TextEditingController(), p = TextEditingController();
                                                                                                                                                                                                                                            String err = '';
                                                                                                                                                                                                                                              bool busy = false;
                                                                                                                                                                                                                                                Future<void> go() async {
                                                                                                                                                                                                                                                    setState(() { busy = true; err = ''; });
                                                                                                                                                                                                                                                        try {
                                                                                                                                                                                                                                                              await FirebaseAuth.instance
                                                                                                                                                                                                                                                                        .signInWithEmailAndPassword(email: e.text.trim(), password: p.text);
                                                                                                                                                                                                                                                                            } catch (x) {
                                                                                                                                                                                                                                                                                  setState(() => err = 'Login failed. Check email and password.');
                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                          if (mounted) setState(() => busy = false);
                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                              @override
                                                                                                                                                                                                                                                                                                Widget build(BuildContext context) => Scaffold(
                                                                                                                                                                                                                                                                                                        body: SafeArea(
                                                                                                                                                                                                                                                                                                                  child: Padding(
                                                                                                                                                                                                                                                                                                                              padding: const EdgeInsets.all(24),
                                                                                                                                                                                                                                                                                                                                          child: Column(mainAxisAlignment: MainAxisAlignment.center, children: [
                                                                                                                                                                                                                                                                                                                                                        const Text('🛠️ Vehicle Stage Tracker',
                                                                                                                                                                                                                                                                                                                                                                          style: TextStyle(fontSize: 22, fontWeight: FontWeight.bold)),
                                                                                                                                                                                                                                                                                                                                                                                        const SizedBox(height: 24),
                                                                                                                                                                                                                                                                                                                                                                                                      TextField(
                                                                                                                                                                                                                                                                                                                                                                                                                        controller: e,
                                                                                                                                                                                                                                                                                                                                                                                                                                          keyboardType: TextInputType.emailAddress,
                                                                                                                                                                                                                                                                                                                                                                                                                                                            decoration: const InputDecoration(labelText: 'Email', border: OutlineInputBorder())),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const SizedBox(height: 12),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        TextField(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          controller: p,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            obscureText: true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              decoration: const InputDecoration(labelText: 'Password', border: OutlineInputBorder())),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const SizedBox(height: 12),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (err.isNotEmpty) Text(err, style: const TextStyle(color: Colors.red)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const SizedBox(height: 12),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      SizedBox(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        width: double.infinity,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          child: FilledButton(onPressed: busy ? null : go, child: const Text('Login'))),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ]),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              class Home extends StatefulWidget {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                final User user;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const Home({super.key, required this.user});
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    @override
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      State<Home> createState() => _HomeState();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      class _HomeState extends State<Home> {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        int tab = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          int sec = 1; // 1 = Sec-1, 2 = Sec-2, 0 = Total
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            String q = '';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              final db = FirebaseFirestore.instance;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Future<void> addVehicle(List<Map<String, dynamic>> all) async {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    final c = TextEditingController();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        final n = await showDialog<String>(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              context: context,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    builder: (_) => AlertDialog(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            title: const Text('Add vehicle'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    content: TextField(controller: c, autofocus: true, decoration: const InputDecoration(labelText: 'Vehicle number')),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            actions: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      TextButton(onPressed: () => Navigator.pop(context), child: const Text('Cancel')),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                FilledButton(onPressed: () => Navigator.pop(context, c.text.trim()), child: const Text('Add')),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (n == null || n.isEmpty) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (all.any((v) => secOf(v) == sec && (v['no'] as String).toLowerCase() == n.toLowerCase())) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (mounted) ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Vehicle already exists')));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              await db.collection('vehicles').add({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'no': n,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          'sec': sec,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'note': '',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'created': FieldValue.serverTimestamp(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'st': {'0': {'in': today()}},
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    @override
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      Widget build(BuildContext context) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                stream: db.collection('users').doc(widget.user.uid).snapshots(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      builder: (context, us) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              final ud = us.data?.data();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      final admin = canEditSec(ud, 1) || canEditSec(ud, 2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              final canAdd = sec != 0 && canEditSec(ud, sec);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                stream: db.collection('vehicles').snapshots(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          builder: (context, vs) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      final all = (vs.data?.docs ?? []).map((d) => {...d.data(), 'id': d.id}).toList()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ..sort((a, b) => (a['no'] as String).compareTo(b['no'] as String));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                final scoped = sec == 0 ? all : all.where((v) => secOf(v) == sec).toList();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            final list = scoped.where((v) => (v['no'] as String).toLowerCase().contains(q.toLowerCase())).toList();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Widget inner;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (vs.hasError) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  inner = const Center(child: Text('Cannot load data. Check Firestore rules.'));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              } else if (tab == 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            inner = ListView(padding: const EdgeInsets.all(12), children: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Row(children: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Expanded(child: _stat('Total', '${scoped.length}')),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const SizedBox(width: 8),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Expanded(child: _stat('Completed', '${scoped.where((v) => current(v) == 16).length}')),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ]),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (sec == 0)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Padding(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        padding: const EdgeInsets.symmetric(vertical: 4),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            child: Text('Sec-1: ${all.where((v) => secOf(v) == 1).length} vehicles   |   Sec-2: ${all.where((v) => secOf(v) == 2).length} vehicles'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              for (var i = 0; i < 16; i++) _stageCard(i, scoped),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      inner = Column(children: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      Padding(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        padding: const EdgeInsets.all(12),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          child: TextField(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onChanged: (t) => setState(() => q = t),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      decoration: const InputDecoration(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                prefixIcon: Icon(Icons.search), hintText: 'Search vehicle number', border: OutlineInputBorder())),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Expanded(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  child: list.isEmpty
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ? const Center(child: Text('No vehicles'))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              : ListView(children: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        for (final v in list)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ListTile(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  title: Text(v['no'], style: const TextStyle(fontWeight: FontWeight.bold)),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                subtitle: Text('Sec-${secOf(v)}'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              trailing: Chip(label: Text(status(v))),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onTap: () => Navigator.push(context,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              MaterialPageRoute(builder: (_) => Detail(id: v['id'], admin: false))),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ]),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return Scaffold(
